"""Persist host-authored copilot messages to the copilot thread.

Hello's jobs write chat messages no copilot turn produced — the generation
prompt, the template prompt, the welcome message, the training-success and
rollback messages. The jobs call these functions directly, which keeps the rows
in the order they happened: the store is append-only, so a later backfill could
not reorder them.

Host-side by construction; the runtime package only supplies the row shapes.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Any, Optional

import structlog

# Read through the module, not by value: COPILOT_HISTORY_SQLITE_PATH has to
# resolve to the same file the route layer uses.
from rasa.builder import config as builder_config
from rasa.builder.copilot.constants import ROLE_ASSISTANT, ROLE_USER
from rasa.builder.copilot.models import ResponseCategory

if TYPE_CHECKING:
    from rasa.builder.copilot.pydantic_ai.thread_store import SQLiteThreadStore

structlogger = structlog.get_logger()

# Must match the frontend, which reads history under `thread-${projectId}`
# (frontend/src/api/copilot/v2.ts) using the id project-service injects here as
# HELLO_RASA_PROJECT_ID. Disagree and these rows land in a thread nobody reads.
_THREAD_ID_PREFIX = "thread-"


def copilot_thread_id() -> Optional[str]:
    """Return this project's thread id, or ``None`` when it is unknowable.

    Unknowable without ``HELLO_RASA_PROJECT_ID`` — a local run, where the
    frontend falls back to an id derived from the project URL instead.
    """
    project_id = (builder_config.HELLO_RASA_PROJECT_ID or "").strip()
    if not project_id:
        return None
    return f"{_THREAD_ID_PREFIX}{project_id}"


def open_copilot_thread_store() -> "SQLiteThreadStore":
    """Open the thread store for the configured database.

    The lazy import keeps the optional pydantic-ai extra out of this module's
    import-time dependencies. Callers on a hot path should hold on to the
    result.
    """
    from rasa.builder.copilot.pydantic_ai.thread_store import SQLiteThreadStore

    return SQLiteThreadStore(builder_config.COPILOT_HISTORY_SQLITE_PATH)


async def persist_user_message_to_thread(
    text: str, thread_id: Optional[str] = None
) -> None:
    """Append a host-authored user message to the copilot thread.

    Args:
        text: The message text.
        thread_id: An explicit thread id to write to, overriding
            `copilot_thread_id()`. Callers that already know the thread
            id (for example, one supplied by the frontend) pass it here so
            the row lands even when `HELLO_RASA_PROJECT_ID` is unset.
    """
    if not text:
        return

    await _append(text, role=ROLE_USER, thread_id=thread_id)


async def persist_copilot_message_to_thread(
    text: str,
    response_category: ResponseCategory = ResponseCategory.COPILOT,
    thread_id: Optional[str] = None,
) -> None:
    """Append a host-authored copilot message to the copilot thread.

    Skips a message with no text — a bare commit or log block — since thread
    rows hold text only and there would be nothing left to render.

    Args:
        text: The message text.
        response_category: The category to tag the assistant row with.
        thread_id: An explicit thread id to write to, overriding
            `copilot_thread_id()`. Callers that already know the thread
            id (for example, one supplied by the frontend) pass it here so
            the row lands even when `HELLO_RASA_PROJECT_ID` is unset.
    """
    if not text:
        return

    await _append(
        text,
        role=ROLE_ASSISTANT,
        response_category=response_category,
        thread_id=thread_id,
    )


async def _append(
    text: str,
    *,
    role: str,
    response_category: ResponseCategory = ResponseCategory.COPILOT,
    thread_id: Optional[str] = None,
) -> None:
    """Append one row to a thread, swallowing any failure.

    Best-effort like the runtime's own persist hook: the message has already
    streamed, so failing to save it must not break the job the user is watching.

    Args:
        text: The message text.
        role: The row's role (`ROLE_USER` or `ROLE_ASSISTANT`).
        response_category: The category to tag an assistant row with.
        thread_id: An explicit thread id to write to. When `None`, falls
            back to `copilot_thread_id()`.
    """
    thread_id = thread_id if thread_id is not None else copilot_thread_id()
    if thread_id is None:
        structlogger.debug("copilot.thread_history.no_thread_id", role=role)
        return

    try:
        row = _build_row(text, role=role, response_category=response_category)
        await open_copilot_thread_store().append_messages(thread_id, [row])
        structlogger.debug(
            "copilot.thread_history.persisted",
            thread_id=thread_id,
            role=role,
        )
    except Exception as exc:
        structlogger.warning(
            "copilot.thread_history.persist_failed",
            thread_id=thread_id,
            role=role,
            error=str(exc),
        )


def _build_row(
    text: str, *, role: str, response_category: ResponseCategory
) -> dict[str, Any]:
    """Build the AG-UI row for the message, in the runtime's own shape."""
    from rasa.builder.copilot.pydantic_ai.persisted_messages import (
        assistant_text_row,
        user_row,
    )

    if role == ROLE_USER:
        return user_row(text)
    return assistant_text_row(text, response_category=response_category.value)
